<style>
 .procedure-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:20px}.procedure-list{display:grid;gap:10px;max-height:560px;overflow:auto}.procedure-record{display:block;width:100%;text-align:left;border:1px solid var(--line);border-radius:7px;background:white;color:var(--ink);padding:16px}.procedure-record strong,.procedure-record small{display:block;overflow-wrap:anywhere}.procedure-record small{margin-top:7px;line-height:1.6;color:var(--muted)}.procedure-record[aria-pressed=true]{border-color:#9b8245;box-shadow:inset 3px 0 var(--gold)}.procedure-facts{display:grid;grid-template-columns:minmax(90px,.5fr) minmax(0,1fr);gap:8px;font-size:12px}.procedure-facts dt{color:var(--muted)}.procedure-facts dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}.procedure-notice{padding:13px;border-left:3px solid #b08a45;background:#faf5e9;line-height:1.7;font-size:12px}.procedure-form{border-top:1px solid var(--line);padding-top:20px;margin-top:18px}.procedure-form fieldset{border:0;margin:0;padding:0;min-width:0}.procedure-form input,.procedure-form select,.procedure-form textarea{width:100%;min-width:0}.procedure-form .procedure-confirm{display:flex;gap:10px;align-items:center;min-height:44px;line-height:1.6}.procedure-confirm input{width:22px;height:22px;flex:0 0 22px}.procedure-history{max-height:300px;overflow:auto;font-size:12px}.procedure-history article{padding:12px 0;border-top:1px solid var(--line)}.procedure-period{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.procedure-preview{display:grid;gap:14px}.procedure-preview article{padding:15px;border:1px solid var(--line);border-radius:7px;overflow-wrap:anywhere}.procedure-preview h4{font-size:16px;margin:0 0 8px}.procedure-preview p{font-size:12px;line-height:1.7}.procedure-preview pre{font:12px/1.6 system-ui,sans-serif;white-space:pre-wrap;overflow-wrap:anywhere}.procedure-scroll{max-height:540px;overflow:auto;display:grid;gap:8px}#certificate-workspace,#quarterly-workspace{margin-top:24px;overflow-wrap:anywhere}#certificate-workspace button,#quarterly-workspace button,#quarterly-workspace a.button{min-height:44px}#certificate-workspace :focus-visible,#quarterly-workspace :focus-visible{outline:3px solid #738a5a;outline-offset:3px}@media(max-width:1100px){.procedure-grid{grid-template-columns:1fr}.procedure-list{max-height:360px}}@media(max-width:650px){.procedure-period{grid-template-columns:1fr}.procedure-facts{grid-template-columns:1fr}.procedure-facts dd{margin-bottom:8px}.procedure-form input,.procedure-form select,.procedure-form textarea,#quarterly-period input,#quarterly-period select{font-size:16px}.procedure-record{padding:14px}}
 #quarterly-period,#quarterly-period label,.procedure-period,.procedure-preview>*,.procedure-scroll>*{min-width:0}#quarterly-period input,#quarterly-period select{width:100%;min-width:0;max-width:100%;min-height:44px}#certificate-workspace summary{min-height:44px;padding:10px 0;cursor:pointer}
 #quarterly-period select{white-space:normal}
</style>
<section class="panel stack" id="certificate-workspace" aria-labelledby="certificate-heading" hidden>
 <div><div class="eyebrow">Restricted manager records</div><h2 id="certificate-heading">Contractor certificate register</h2><p class="subtle">Keep the accepted record separate from a proposed replacement, with an explicit review history.</p></div>
 <p class="procedure-notice">Metadata and manager review only. This register does not validate insurance coverage, store certificate files or send reminders. Warning periods and review dates are entered by your authorized team.</p>
 <p id="certificate-status" class="caption" role="status" aria-live="polite"></p>
 <div id="certificate-body" class="stack" hidden>
  <div class="actions"><button class="button" id="certificate-refresh" type="button">Refresh certificate records</button><button class="button primary" id="certificate-new" type="button">New certificate record</button><button class="button" id="certificate-retry" type="button" hidden>Retry the exact certificate action</button></div>
  <details class="procedure-notice" id="certificate-retained" hidden><summary>Review retained exact certificate action</summary><p>Its outcome has not been confirmed in this browser. Retry the same request; editing stays locked. This private workspace draft is restored only after current manager access is checked.</p><pre id="certificate-retained-body"></pre></details>
  <p class="caption" id="certificate-coverage"></p>
  <section><h3>Internal reminder queue</h3><p class="caption">A fresh view of records needing attention. No scheduler, email or SMS dispatch runs from this queue.</p><div class="procedure-list" id="certificate-reminders"></div></section>
  <div class="procedure-grid"><section><h3>Workspace register</h3><div class="procedure-list" id="certificate-list"></div></section><section id="certificate-detail" aria-label="Selected certificate details"></section></div>
  <form class="stack procedure-form" id="certificate-form" hidden>
   <h3 id="certificate-form-heading">New certificate record</h3>
   <fieldset class="stack" id="certificate-fields">
    <label>Existing contractor contact<select id="certificate-contractor" required></select></label>
    <label>Record title<input id="certificate-title" required maxlength="150"></label>
    <label>Renewal contact, if known<input id="certificate-contact" maxlength="500"></label>
    <div class="field-pair"><label>Warning lead days, if agreed<input id="certificate-warning" type="number" min="0" max="3650" step="1"></label><label>Next manager review date, if agreed<input id="certificate-review-date" type="date"></label></div>
    <div id="certificate-initial-proposal" class="stack"><label>Document reference, if known<textarea id="certificate-document" maxlength="500" rows="2"></textarea></label><label>Expiry date, if known<input id="certificate-expiry" type="date"></label><p class="caption">This is a manual reference, not an uploaded file or proof of accepted coverage. Unknown expiry remains unknown until reviewed.</p></div>
   </fieldset>
   <div class="actions"><button class="button primary" id="certificate-save" type="submit">Save proposed certificate record</button><button class="button" id="certificate-form-close" type="button">Close unsent form</button></div>
  </form>
 </div>
</section>
<section class="panel stack" id="quarterly-workspace" aria-labelledby="quarterly-heading" hidden>
 <div><div class="eyebrow">Period activity export</div><h2 id="quarterly-heading">Quarterly activity report</h2><p class="subtle">Preview currently authorized records and recorded activity for a chosen period, then export CSV or JSON.</p></div>
 <p class="procedure-notice">Records show current state; events cover the selected period. Review these fields against your reporting requirements before submission.</p>
 <p id="quarterly-status" class="caption" role="status" aria-live="polite"></p>
 <form class="stack" id="quarterly-period" hidden>
  <div class="procedure-period"><label>Reporting window<select id="quarterly-mode"><option value="calendar_quarter">Calendar quarter</option><option value="date_range">Explicit date range</option></select></label><label>Reporting timezone<input id="quarterly-timezone" value="America/New_York" required maxlength="100"></label></div>
  <div class="procedure-period" id="quarterly-calendar"><label>Year<input id="quarterly-year" type="number" min="2000" max="2100" step="1" required></label><label>Quarter<select id="quarterly-quarter"><option value="1">Q1 · January–March</option><option value="2">Q2 · April–June</option><option value="3">Q3 · July–September</option><option value="4">Q4 · October–December</option></select></label></div>
  <div class="procedure-period" id="quarterly-range" hidden><label>First date, inclusive<input id="quarterly-start" type="date"></label><label>Last date, inclusive<input id="quarterly-end" type="date"></label></div>
  <label>Project filter<select id="quarterly-project"><option value="">All currently authorized projects in this workspace</option></select></label>
  <div class="actions"><button class="button primary" id="quarterly-preview" type="submit">Preview period activity</button><a class="button" id="quarterly-csv" hidden download>Download fresh CSV</a><a class="button" id="quarterly-json" hidden download>Download fresh JSON</a></div>
  <p class="caption">Each download rechecks access and regenerates the selected report. It is a dated snapshot; it does not update after download.</p>
 </form>
 <div class="procedure-preview" id="quarterly-preview-body" aria-live="polite"></div>
</section>
